// Optional local CDP checks share the review fixtures and can be called by a browser driver.
export async function checkBrowser2c({page,sleep}){
 const b64=o=>Buffer.from(JSON.stringify(o)).toString('base64url'),uid='11111111-1111-1111-1111-111111111111',exp=Math.floor(Date.now()/1000)+86400,session={access_token:b64({alg:'HS256',typ:'JWT'})+'.'+b64({sub:uid,exp,aud:'authenticated',role:'authenticated'})+'.sig',refresh_token:'local',token_type:'bearer',expires_in:86400,expires_at:exp,user:{id:uid,aud:'authenticated',role:'authenticated',user_metadata:{full_name:'Cartographer'}}};
 await page.size(1400,900);await page.goto('http://127.0.0.1:8979/?map=night-harbor');await page.eval('localStorage.setItem("sb-127-auth-token",'+JSON.stringify(JSON.stringify(session))+')');await page.goto('http://127.0.0.1:8979/?map=night-harbor');await sleep(500);
 const test=async(name,expression)=>{const result=await page.eval(expression);assert.equal(result,true,name+': '+JSON.stringify(result));console.log('PASS browser '+name);};
 await page.eval("window.atlasCommunity.change(labelData.labels.find(p=>p.kind==='exit'),'edit-label')");await sleep(500);
 await test('R03 floating-frame',`(()=>{const d=document.getElementById('community-dialog'),f=document.getElementById('map-frame').getBoundingClientRect(),r=d.getBoundingClientRect();d.scrollTop=d.scrollHeight;const a=d.querySelector('.dialog-actions').getBoundingClientRect();return r.left>=f.left&&r.right<=f.right&&r.top>=f.top&&r.bottom<=f.bottom&&a.bottom<=r.bottom&&a.top>=r.top})()`);
 await test('R05 unchanged-exit-guard',`(()=>{let asked=false;window.confirm=()=>{asked=true;return false;};[...document.querySelectorAll('#community-dialog button')].find(b=>b.textContent==='Cancel').click();return !document.getElementById('community-dialog').open&&!asked})()`);
 await page.eval("document.getElementById('community-dialog').close();openEditor({id:'personal-qa',name:'Bounty',category:'Bank',note:'Facts',x:20,y:30});document.getElementById('marker-form').classList.add('bounty-mode')");await sleep(100);
 await test('R08 bounty-readonly',`(()=>{const ids=['name','category','trade','trainer-class','vendor-kind','wiki','pin-preview','pin-colours'];return ids.every(id=>{const e=document.getElementById(id);return !e||!e.getClientRects().length})})()`);await page.eval("document.getElementById('editor').close();document.querySelector('.account-button').click();[...document.querySelectorAll('.account-menu button')].find(b=>b.textContent.startsWith('Review')).click()");await sleep(700);
 await test('V03 visible-group-headings',`(()=>{const list=document.getElementById('desk-list'),r=list.getBoundingClientRect(),map=list.querySelector('.desk-map').getBoundingClientRect(),place=list.querySelector('.desk-place');return map.top>=r.top&&map.bottom<=r.bottom&&place.getBoundingClientRect().top>=map.bottom&&/changes? to /.test(place.textContent)})()`);
 await test('V02 readable-badges',`(()=>{const ring=document.querySelector('.review-ring').getBoundingClientRect(),numbers=[...document.querySelectorAll('.review-pin-number')].map(e=>e.getBoundingClientRect()),hit=(a,b)=>a.left<b.right&&a.right>b.left&&a.top<b.bottom&&a.bottom>b.top;return numbers.length>0&&numbers.every((n,i)=>!hit(n,ring)&&numbers.slice(i+1).every(o=>!hit(n,o)))})()`);
 await page.size(390,844,true);await sleep(300);await page.eval("status('Suggestion saved.');window.atlasOfferUndo('Back to waiting',async()=>{})");await sleep(100);
 await test('V01 phone-toast-above-sheet',`(()=>{const sheet=document.getElementById('journal').getBoundingClientRect(),toast=document.getElementById('status').getBoundingClientRect();return toast.bottom<=sheet.top-8})()`);await page.eval("document.querySelector('.desk-more').click()");await sleep(200);
 await test('V01 expanded-toast-above-sheet',`document.getElementById('status').getBoundingClientRect().bottom<=document.getElementById('journal').getBoundingClientRect().top-8`);
 await page.eval("window.atlasCommunity.closeReview();const p=labelData.labels.find(p=>p.kind==='exit'&&p.toMap);openPlace({...p,kind:'label'},3.6)");await sleep(400);
 await test('R16 phone-travel-action',`(()=>{const popup=document.querySelector('.leaflet-popup-content'),tag=popup.querySelector('.tag'),button=popup.querySelector('.level-link').getBoundingClientRect(),title=document.querySelector('.map-title').getBoundingClientRect();return tag.textContent==='Zone exit'&&!(button.left<title.right&&button.right>title.left&&button.top<title.bottom&&button.bottom>title.top)})()`);
}
